function headerTitle(type){return {home:['Volver a casa','Elige un centro urbano'],build:['Construir','Elige y coloca en el terreno'],grow:['Cultivar','8 cultivos de muestra'],magic:['Magia','Poderes del espíritu'],menu:['Pausa','Wild Guardians · HUD Lab'],options:['Opciones','Preferencias de la demostración'],lab:['Laboratorio','Prueba cada estado de la interfaz'],title:['Wild Guardians','Laboratorio de interfaz']}[type]}
