function openMenu(type){if(!ready||state.hiring.pending)return;if(state.modal===type){closeMenu();return}sound();focusReturn=document.activeElement;state.modal=type;state.systemPaused=['menu','options','lab','title'].includes(type);stage.classList.toggle('system-open',state.systemPaused);selection=null;placement=null;$('contextPanel').style.display='none';$('placementBanner').style.display='none';let [title,subtitle]=headerTitle(type);host.innerHTML=`<section class="panel" role="dialog" aria-label="${title}" aria-modal="${state.systemPaused}"><canvas class="frame-canvas" aria-hidden="true"></canvas><header class="panel-head"><div><h2 class="panel-title">${title}</h2><p class="panel-subtitle">${subtitle}</p></div><button class="close-panel" data-do="close" aria-label="Cerrar">×</button></header><div class="panel-body">${modalContent(type)}</div></section>`;host.style.display='block';document.querySelectorAll('[data-menu]').forEach(b=>b.classList.toggle('active',b.dataset.menu===type));$('tutorial').style.visibility=state.systemPaused?'hidden':'visible';placeModal();updateCooldowns();host.querySelector('.close-panel')?.focus({preventScroll:true})}
