function beginPlacement(kind,type){if(state.hiring.pending)return;closeMenu();selection=null;placement={kind,type,point:[gfx.camera.target[0],0,gfx.camera.target[2]],valid:true};const name=kind==='town'?'Centro urbano':kind==='wall'?'Muralla':kind==='crop'?CROP_TYPES[type].name:SPELLS[type].name;$('placementBanner').querySelector('span').innerHTML=`<b>${name}</b>${kind==='spell'?'Toca la zona para usar el poder.':'Toca un espacio libre del terreno.'}`;$('placementBanner').style.display='flex';$('contextPanel').style.display='none';sound()}
